<?php function selected($a,$b):string{return (string)$a===(string)$b?'selected':'';} require_once __DIR__.'/../bootstrap.php';require_admin();$page=valid_page();$per=25;$anime=(int)($_GET['anime_id']??0);$q=trim($_GET['q']??'');$where=[];$p=[];if($anime){$where[]='e.anime_id=?';$p[]=$anime;}if($q!==''){$where[]='(a.title LIKE ? OR e.title LIKE ?)';$p[]="%$q%";$p[]="%$q%";}$w=$where?' WHERE '.implode(' AND ',$where):'';$c=$pdo->prepare("SELECT COUNT(*) FROM episodes e JOIN anime a ON a.id=e.anime_id$w");$c->execute($p);$pages=max(1,ceil($c->fetchColumn()/$per));$s=$pdo->prepare("SELECT e.*,a.title anime_title FROM episodes e JOIN anime a ON a.id=e.anime_id$w ORDER BY a.title,e.number LIMIT ? OFFSET ?");foreach($p as $i=>$v)$s->bindValue($i+1,$v);$s->bindValue(count($p)+1,$per,PDO::PARAM_INT);$s->bindValue(count($p)+2,($page-1)*$per,PDO::PARAM_INT);$s->execute();$title='Episodes — AniRead';include __DIR__.'/../includes/header.php';?><h1>Episodes</h1><form class="filters"><input class="input" name="q" value="<?=e($q)?>" placeholder="Anime or episode title"><button class="btn">Filter</button></form><p><a class="btn" href="episode-edit.php">Add episode</a></p><table class="table"><tr><th>Anime</th><th>Episode</th><th>Title</th><th>Active</th><th></th></tr><?php foreach($s as $x):?><tr><td><?=e($x['anime_title'])?></td><td><?=e($x['number'])?></td><td><?=e($x['title'])?></td><td><?=$x['active']?'Yes':'No'?></td><td><a class="btn alt" href="episode-edit.php?id=<?=$x['id']?>">Edit</a></td></tr><?php endforeach;?></table><?php page_links($page,$pages,'episodes.php?q='.rawurlencode($q));include __DIR__.'/../includes/footer.php';
